res_obs = primitives.call(name="observe_vlabench_scene", prompt="observe scene")
if res_obs.ok:
    oge = res_obs.output.get("object_grounding_evidence", {})
    print("grasped:", oge.get("grasped_obj_name"))
    ee = oge.get("entity_evidence", {})
    for name in ["salad_dressing", "dishes", "pan_unseen", "sugar"]:
        if name in ee:
            print(name, "xpos:", ee[name].get("xpos"), "xquat:", ee[name].get("xquat"))
